/* Generated by the port verification harness: expected strings come from
 * relations.py solve() (see gen_traces.py render_call/run_call token format).
 * Standalone host test binary; build:
 *   cc -O2 -Wall -Wextra -Werror -o test_solvers test_solvers.c solvers.c -lm
 */
#include <stdio.h>
#include <string.h>

#include "solvers.h"

typedef struct {
	const char *a[6];
	const char *want;
} tcase;

typedef struct {
	long long n, d;
	const char *want;
} dcase;

static int check_rel(const char *name, const tcase *v, int n, int na,
                     int *total)
{
	char out[256];
	int i, bad = 0;

	for (i = 0; i < n; i++) {
		int rc = solvers_solve(name, v[i].a, na, out, sizeof(out));

		(*total)++;
		if (rc != 0 || strcmp(out, v[i].want) != 0) {
			if (bad < 15)
				fprintf(stderr,
					"FAIL %s #%d args={%s,%s,%s,%s,%s,%s} rc=%d got='%s' want='%s'\n",
					name, i, v[i].a[0], v[i].a[1], v[i].a[2],
					v[i].a[3], v[i].a[4], v[i].a[5], rc, out,
					v[i].want);
			bad++;
		}
	}
	printf("%-12s %5d cases, %d mismatches\n", name, n, bad);
	return bad;
}

static int check_dec(const dcase *v, int n, int *total)
{
	char out[64];
	int i, bad = 0;

	for (i = 0; i < n; i++) {
		int rc = solvers_dec4(v[i].n, v[i].d, out, sizeof(out));

		(*total)++;
		if (rc != 0 || strcmp(out, v[i].want) != 0) {
			if (bad < 15)
				fprintf(stderr,
					"FAIL dec4 %lld/%lld rc=%d got='%s' want='%s'\n",
					v[i].n, v[i].d, rc, out, v[i].want);
			bad++;
		}
	}
	printf("%-12s %5d cases, %d mismatches\n", "dec4", n, bad);
	return bad;
}

static int check_errors(int *total)
{
	char out[64];
	const char *a2[2] = { "1", "2" };
	const char *a3[3] = { "1", "2", "3" };
	int bad = 0;

	(void)a2;
	(void)a3;
	if (solvers_solve("no_such", a2, 2, out, sizeof(out)) != -1) {
		fprintf(stderr, "FAIL error: unknown relation rc\n");
		bad++;
	}
	(*total)++;
	if (solvers_solve("ohm_i", a2, 1, out, sizeof(out)) != -2) {
		fprintf(stderr, "FAIL error: wrong nargs rc\n");
		bad++;
	}
	(*total)++;
	{
		const char *bada[2] = { "1.2.3", "4" };

		if (solvers_solve("ohm_i", bada, 2, out, sizeof(out)) != -3) {
			fprintf(stderr, "FAIL error: bad token rc\n");
			bad++;
		}
	}
	(*total)++;
	{
		const char *sunga[6] = { "1", "1", "1", "2", "2", "5" };

		if (solvers_solve("linear2", sunga, 6, out, sizeof(out)) != -4) {
			fprintf(stderr, "FAIL error: singular system rc\n");
			bad++;
		}
	}
	(*total)++;
	{
		const char *cplxa[3] = { "1", "0", "1" };

		if (solvers_solve("quad_solve", cplxa, 3, out, sizeof(out)) != -4) {
			fprintf(stderr, "FAIL error: complex roots rc\n");
			bad++;
		}
	}
	(*total)++;
	{
		const char *emptya[3] = { "0", "0", "5" };

		if (solvers_solve("quad_solve", emptya, 3, out, sizeof(out)) != 0 ||
		    out[0] != '\0') {
			fprintf(stderr, "FAIL error: quad a=b=0 should be empty string\n");
			bad++;
		}
	}
	return bad;
}

